				t.Fatalf("Decode(%q) returned error: %v", tt.input, err)
			}
			if got["message"] != (Value{Type: "string", Value: tt.want}) {
				t.Fatalf("Decode(%q) = %v, want %q", tt.input, got["message"], tt.want)
			}
		})
	}
}

