func decodeString(raw string) (Value, int, error) {
	if strings.HasPrefix(raw, "\"\"\"") {
		return decodeQuoted(raw, '"', true)
	}
	if strings.HasPrefix(raw, "'''") {
		return decodeQuoted(raw, '\'', true)
	}
	if strings.HasPrefix(raw, "\"") {
		return decodeQuoted(raw, '"', false)
	}
	if strings.HasPrefix(raw, "'") {
